from lib import *
S = SS('p42')
steps = [
    step("本机服务器(我按条件请求的常见语义实现的,不是某个真实服务器)对 200 KB 页面的几种请求。第一次 GET:200,200 KB,1.6 ms,响应头带 ETag=\"p0-v1\" 和 Last-Modified。带 If-None-Match 为该 ETag、带 If-Modified-Since 为该日期、两个头一起带:都得到 304,响应体 0 字节,耗时 0.5–0.8 ms(对比首次 1.6 ms);ETag 写错得到 200,完整 204800 字节;If-None-Match 是列表(含正确的一个)304,If-None-Match: * 304,W/ 弱校验前缀 304(这几条是我的服务器的实现);ETag 去掉引号、If-Modified-Since 是更早的时间、日期格式乱写:都是 200。304 响应里仍带 ETag 和 Last-Modified 头。", t=tl(S(1)), done=lidx(S(1), 'If-None-Match: ETag', 'If-Modified-Since: Last-Modified', '两个头一起带'), mark=lidx(S(1), '带了错误的 ETag', '去掉引号', '格式乱写'), b=bars([['首次 GET 响应体 KB', 200, '200'], ['304 响应体 KB', 0, '0'], ['错误 ETag 的响应体 KB', 200, '200']], 200, done=[1], mark=[2]), kv=KV([['条件头匹配', '304,响应体 0 字节'], ['不匹配或写错', '200,完整下载'], ['304 响应头', '仍带 ETag / Last-Modified']], ['条件头匹配'])),
    step("抓 100 个页面(各 200 KB)两遍,第二遍前有 10 个页面更新了。第一遍响应体共 19.5 MiB(200 × 100)。第二遍:无条件请求,响应体 19.5 MiB(又是 200 × 100,0.05 秒);带 If-None-Match(客户端自己保存了 ETag 和内容):响应体只有 2.0 MiB(200 × 10、304 × 90),0.03 秒,客户端复用了本地保存的 90 个页面。requests 本身不做缓存,存 ETag 和内容要自己写。", t=tl(S(2)), done=lidx(S(2), '带 If-None-Match'), mark=lidx(S(2), '无条件请求'), b=bars([['第二遍·无条件 MiB', 19.5, '19.5'], ['第二遍·条件请求 MiB', 2.0, '2.0']], 20, mark=[0], done=[1]), kv=KV([['无条件请求', '19.5 MiB(200 × 100)'], ['If-None-Match', '2.0 MiB(200 × 10,304 × 90)'], ['客户端要做的', '自己存 ETag 和内容']], ['If-None-Match'])),
    step("Last-Modified 只精确到秒,同一秒内内容改了两次就可能被漏掉:内容从 version 1 变成 version 2,而 Last-Modified 保持不变(场景是我手工模拟的:服务器在同一秒内更新而时间戳没变),带 If-Modified-Since 的请求得到 304——客户端会认为没变,实际已经变了。换成只用 ETag:内容再变一次后,带旧 ETag 的请求得到 200,拿到新内容。ETag 是内容版本的标识,更可靠(前提是服务器真的在内容变化时更新它)。", t=tl(S(3)), done=lidx(S(3), '换成只用 ETag'), mark=lidx(S(3), '内容从 version 1'), kv=KV([['Last-Modified 没变', '304,错过更新'], ['ETag 变了', '200,拿到新内容'], ['原因', 'HTTP-date 只到秒']], ['Last-Modified 没变'])),
    step("服务器不支持条件请求(动态页面,响应头里没有 ETag 也没有 Last-Modified):带 If-None-Match 和 If-Modified-Since 重复请求得到 200,响应体 200 KB——条件头被无视,每次都完整下载。条件请求只在服务器支持时才省流量,爬虫不能假定一定有用。", t=tl(S(4)), done=lidx(S(4), '响应头里有 ETag'), kv=KV([['响应头', '没有 ETag,没有 Last-Modified'], ['带条件头', '仍然 200 完整下载'], ['结论', '要看服务器是否支持']], ['结论'])),
    step("同一个页面(200 KB)重复访问 100 次:每次都完整下载 —— 服务器收到 100 个请求(200 × 100),响应体 19.5 MiB,44 ms;每次都带 If-None-Match 重新验证 —— 仍是 100 个请求(200 × 1、304 × 99),响应体 0.2 MiB,32 ms;遵守 Cache-Control: max-age=60,新鲜期内不发请求 —— 服务器只收到 1 个请求,0.2 MiB,1 ms。条件请求省的是流量(体积),max-age 省的是请求本身。", t=tl(S(5)), done=lidx(S(5), 'max-age=60', '重新验证'), mark=lidx(S(5), '完整下载'), b=bars([['完整下载:服务器收到请求', 100, '100'], ['重新验证:服务器收到请求', 100, '100'], ['max-age:服务器收到请求', 1, '1']], 100, mark=[0], done=[2]), kv=KV([['完整下载', '100 个请求,19.5 MiB'], ['条件请求', '100 个请求,0.2 MiB'], ['max-age', '1 个请求,0.2 MiB']], ['max-age'])),
]
A = mkartp('p42', 42, '爬虫,增量抓取,ETag,Last-Modified,304,条件请求,Cache-Control,Python,真实验证,动画演示',
    '实测条件请求对爬虫增量抓取的作用:200 KB 页面带正确 If-None-Match 得到 304 且响应体 0 字节;100 个页面第二遍,10 个更新,响应体从 19.5 MiB 降到 2.0 MiB;Last-Modified 不变时 304 会错过更新;同一页面重复访问 100 次,max-age 内只需要 1 个请求。',
    '重复抓同一批页面时,多数页面其实没变。HTTP 的条件请求(ETag、Last-Modified、304)能让服务器在没变时不重发响应体。这篇在本机服务器上量它能省多少、什么写法有效、什么情况会错过更新,以及和 Cache-Control: max-age 的区别。',
    [('19.5 → 2.0 MiB', '100 个页面第二遍抓取(10 个更新)的响应体总量,无条件请求 对 带 If-None-Match'), ('304 + 0 字节', '带正确的条件头时,200 KB 页面的响应'), ('1 个请求', '遵守 max-age=60 时,同一页面访问 100 次服务器收到的请求数(重新验证是 100 个)')],
    [('条件头怎么写', '<p>带上次拿到的 <code>ETag</code> 作为 <code>If-None-Match</code>,或带 <code>Last-Modified</code> 作为 <code>If-Modified-Since</code>,服务器认为没变就回 <code>304</code> 和空的响应体。这里的匹配细节(列表、<code>*</code>、弱校验前缀、去引号的 ETag 不匹配)是我写的服务器的实现,真实服务器可能不同。</p>'),
     ('增量抓取的收益', '<p>100 个页面抓两遍,10 个更新:无条件请求第二遍又下载 19.5 MiB;带 <code>If-None-Match</code> 只下载 2.0 MiB(10 个更新的页面),90 个直接复用本地保存的内容。requests 不会替你缓存,要自己保存 ETag 和内容。</p>'),
     ('Last-Modified 的坑', '<p>HTTP-date 只精确到秒。内容变了而 <code>Last-Modified</code> 没变(同一秒内更新两次),带 <code>If-Modified-Since</code> 的请求会得到 304,错过更新;ETag 在内容变了就拿到新内容。我在本机用手工设定的方式复现了这个场景。</p>'),
     ('服务器不支持', '<p>动态页面常常既没有 <code>ETag</code> 也没有 <code>Last-Modified</code>,条件头被无视,每次都是完整的 200。</p>'),
     ('max-age 与重新验证', '<p>条件请求每次仍要一次往返(服务器收到 100 个请求,但响应体只有 0.2 MiB);<code>Cache-Control: max-age</code> 在新鲜期内连请求都不发(只收到 1 个请求)。爬虫的“礼貌”和速度都受益于后者,代价是在新鲜期内看不到更新。</p>')],
    steps,
    [ENV_P + '。服务器:100 个页面 /p/<i>(各 200 KB),可配置只用 ETag、只用 Last-Modified、两者、都不用;ETag 形如 "p<i>-v<version>";条件请求的匹配逻辑和 304 响应是我按常见语义写的;客户端 requests 2.34.2,自己保存 ETag 与内容;max-age 的新鲜度判断是我写的最小实现;每项各跑一次',
     '没有验证:真实服务器和 CDN 的 ETag 行为(例如多台后端各自生成不同的 ETag、压缩和不压缩的版本 ETag 不同);Vary 头对缓存的影响;requests-cache 等现成库;Cache-Control 的 no-cache、no-store、stale-while-revalidate 等指令;HEAD 请求用于检测更新;sitemap 的 lastmod 与条件请求的配合(下一篇)'],
    '条件请求与增量抓取')
